/* nd_rec.h: record form of the gSP and gDP macros (plan_s10_path CORE-1, CORE-2c). A file opts in with -include nd_rec.h (CMake).
 * A one-slot leaf's record is its N64 word: the opcode is the setter id and the walker case runs the setter (CORE-2b). So a leaf writes its
 * slots in every list, the main list included, and the walker runs them as before. Multi-slot records (texrect by value, vertex pointer:
 * CORE-3 and CORE-4) are not here yet. Any pkt is evaluated once.
 * nd_rec_leaf.h is generated by 3ds/tools/gen_nd_gbi.py. The bridge leaves (nd_gbi.h) are the form of the files that do not opt in. */
#ifndef ND_REC_H
#define ND_REC_H

#include "nd_gbi.h"

/* One leaf: nslots 8-byte slots at at, copied from the words w (the bridge count of ops is in the leaf macro). */
void nd_rec_leaf(void* at, const void* w, unsigned nslots);

#include "nd_rec_leaf.h"

#endif
